INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI001', 'HDSAT-RW-M23-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A solar panel is a device that converts sunlight into electricity by using multiple solar modules that consist of photovoltaic (PV) cells. PV cells are made of materials that produce excited electrons when exposed to light. These electrons flow through a circuit and produce direct current electricity, which can be used to power various devices or be stored in batteries. Solar panels can be known as solar cell panels, or solar electric panels. Solar panels are usually arranged in groups called arrays or systems. A photovoltaic system consists of one or more solar panels, an inverter that converts direct current electricity to alternating current where it is necessary, and sometimes other components such as charge controllers, meters, or solar trackers to maximize direct sunlight. Most panels are in solar farms or rooftop solar panels, which supply the electricity grid. Solar panels use a renewable and clean source of energy, and reduce greenhouse gas emissions compared to hydrocarbon-sourced energy. However, they depend on the availability and intensity of sunlight, require cleaning, and have high initial costs. Solar panels are widely used for residential, commercial, and industrial purposes, as well as in space, often together with batteries. == History == === Early developments === In 1839, the ability of some materials to create an electrical charge from light exposure was first observed by the French physicist Edmond Becquerel.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Solar panels convert sunlight into electricity through photovoltaic cells, with environmental benefits and practical limits."}, {"id": "B", "text": "Solar panels convert electricity into sunlight."}, {"id": "C", "text": "Solar panels work equally well at night."}, {"id": "D", "text": "Solar panels produce no greenhouse gas reductions compared with fossil fuels."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Solar panel", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Solar_panel', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI001', 'A', ARRAY['A']::TEXT[], 'The passage defines solar panels, explains the photovoltaic process, and lists both advantages and drawbacks.', '{"B": "The text says panels convert sunlight into electricity.", "C": "The text says they depend on the availability and intensity of sunlight.", "D": "The text says they reduce greenhouse gas emissions compared to hydrocarbon-sourced energy."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF001', 'HDSAT-RW-M23-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A solar panel is a device that converts sunlight into electricity by using multiple solar modules that consist of photovoltaic (PV) cells. PV cells are made of materials that produce excited electrons when exposed to light. These electrons flow through a circuit and produce direct current electricity, which can be used to power various devices or be stored in batteries. Solar panels can be known as solar cell panels, or solar electric panels. Solar panels are usually arranged in groups called arrays or systems. A photovoltaic system consists of one or more solar panels, an inverter that converts direct current electricity to alternating current where it is necessary, and sometimes other components such as charge controllers, meters, or solar trackers to maximize direct sunlight. Most panels are in solar farms or rooftop solar panels, which supply the electricity grid. Solar panels use a renewable and clean source of energy, and reduce greenhouse gas emissions compared to hydrocarbon-sourced energy. However, they depend on the availability and intensity of sunlight, require cleaning, and have high initial costs. Solar panels are widely used for residential, commercial, and industrial purposes, as well as in space, often together with batteries. == History == === Early developments === In 1839, the ability of some materials to create an electrical charge from light exposure was first observed by the French physicist Edmond Becquerel.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF001', 'A', ARRAY['A']::TEXT[], 'The passage identifies the inverter as the component that converts DC to AC.', '{"D": "The text says an inverter converts direct current to alternating current where necessary.", "B": "Batteries store electricity; they do not create sunlight.", "C": "A charge controller regulates charging, not current type."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-TS001', 'HDSAT-RW-M23-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A solar panel is a device that converts sunlight into electricity by using multiple solar modules that consist of photovoltaic (PV) cells. PV cells are made of materials that produce excited electrons when exposed to light. These electrons flow through a circuit and produce direct current electricity, which can be used to power various devices or be stored in batteries. Solar panels can be known as solar cell panels, or solar electric panels. Solar panels are usually arranged in groups called arrays or systems. A photovoltaic system consists of one or more solar panels, an inverter that converts direct current electricity to alternating current where it is necessary, and sometimes other components such as charge controllers, meters, or solar trackers to maximize direct sunlight. Most panels are in solar farms or rooftop solar panels, which supply the electricity grid. Solar panels use a renewable and clean source of energy, and reduce greenhouse gas emissions compared to hydrocarbon-sourced energy. However, they depend on the availability and intensity of sunlight, require cleaning, and have high initial costs. Solar panels are widely used for residential, commercial, and industrial purposes, as well as in space, often together with batteries. == History == === Early developments === In 1839, the ability of some materials to create an electrical charge from light exposure was first observed by the French physicist Edmond Becquerel.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that solar panels should replace all other energy sources."}, {"id": "B", "text": "It defines solar panels, explains how they produce electricity, and lists their benefits and limitations."}, {"id": "C", "text": "It traces the history of solar power from 1839 to today."}, {"id": "D", "text": "It compares solar panels with wind turbines in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Solar panel", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Solar_panel', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-TS001', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition to mechanism and then to advantages and disadvantages.', '{"C": "1839 appears only in the final sentence about early observations.", "D": "Wind turbines are not discussed.", "A": "The text describes benefits and drawbacks without advocating replacement."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CE001', 'HDSAT-RW-M23-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A solar panel is a device that converts sunlight into electricity by using multiple solar modules that consist of photovoltaic (PV) cells. PV cells are made of materials that produce excited electrons when exposed to light. These electrons flow through a circuit and produce direct current electricity, which can be used to power various devices or be stored in batteries. Solar panels can be known as solar cell panels, or solar electric panels. Solar panels are usually arranged in groups called arrays or systems. A photovoltaic system consists of one or more solar panels, an inverter that converts direct current electricity to alternating current where it is necessary, and sometimes other components such as charge controllers, meters, or solar trackers to maximize direct sunlight. Most panels are in solar farms or rooftop solar panels, which supply the electricity grid. Solar panels use a renewable and clean source of energy, and reduce greenhouse gas emissions compared to hydrocarbon-sourced energy. However, they depend on the availability and intensity of sunlight, require cleaning, and have high initial costs. Solar panels are widely used for residential, commercial, and industrial purposes, as well as in space, often together with batteries. == History == === Early developments === In 1839, the ability of some materials to create an electrical charge from light exposure was first observed by the French physicist Edmond Becquerel.', 'Which quotation from the text most directly supports the claim that solar panels have drawbacks?', '[{"id": "A", "text": "However, they depend on the availability and intensity of sunlight, require cleaning, and have high initial costs."}, {"id": "B", "text": "Solar panels are usually arranged in groups called arrays or systems."}, {"id": "C", "text": "Solar panels use a renewable and clean source of energy."}, {"id": "D", "text": "A solar panel is a device that converts sunlight into electricity by using multiple solar modules that consist of photovoltaic cells."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Solar panel", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Solar_panel', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CE001', 'A', ARRAY['A']::TEXT[], 'The correct quotation lists the dependence on sunlight, cleaning needs, and high initial costs.', '{"D": "This sentence defines the device.", "C": "This sentence describes an advantage.", "B": "This sentence describes how panels are arranged."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI002', 'HDSAT-RW-M23-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A wind turbine is a device that converts the kinetic energy of wind into electrical energy. As of 2024, hundreds of thousands of large turbines, in installations known as wind farms, were generating over 1,136 gigawatts of power, with 117 GW added each year. Wind turbines are an increasingly important source of intermittent renewable energy, and are used in many countries to lower energy costs and reduce reliance on fossil fuels. One study claimed that, as of 2009, wind had the "lowest relative greenhouse gas emissions, the least water consumption demands and the most favorable social impacts" compared to photovoltaic, hydro, geothermal, coal and gas energy sources. Wind turbines are manufactured in a wide range of sizes, with either horizontal or vertical axes, though horizontal is most common. Commercial power production horizontal-axis turbines usually have three blades, upwind of their towers. Vertical-axis turbines can be made to varied designs, including the "eggbeater" Darrieus, the giromill with straight blades, the Savonius with scoops suitable for rooftops and ships, airborne with wings tethered to the ground, floating (mounted on a floating platform), and various unconventional types such as with counter-rotating blades. Blades are most commonly made of glass fiber composites, but carbon fiber which is stiffer, stronger, and less dense is also used.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "All wind turbines use vertical axes."}, {"id": "B", "text": "Wind turbines convert electricity into wind."}, {"id": "C", "text": "Wind power produces more greenhouse gases than coal."}, {"id": "D", "text": "Wind turbines convert wind into electricity at large scale and come in many designs, though wind is an intermittent resource."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Wind turbine", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Wind_turbine', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI002', 'D', ARRAY['D']::TEXT[], 'The passage describes the technology, its scale, its designs, and its environmental profile.', '{"B": "The text says turbines convert the kinetic energy of wind into electrical energy.", "A": "The text says horizontal-axis turbines are most common.", "C": "The text cites a study finding wind had the lowest relative greenhouse gas emissions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF002', 'HDSAT-RW-M23-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A wind turbine is a device that converts the kinetic energy of wind into electrical energy. As of 2024, hundreds of thousands of large turbines, in installations known as wind farms, were generating over 1,136 gigawatts of power, with 117 GW added each year. Wind turbines are an increasingly important source of intermittent renewable energy, and are used in many countries to lower energy costs and reduce reliance on fossil fuels. One study claimed that, as of 2009, wind had the "lowest relative greenhouse gas emissions, the least water consumption demands and the most favorable social impacts" compared to photovoltaic, hydro, geothermal, coal and gas energy sources. Wind turbines are manufactured in a wide range of sizes, with either horizontal or vertical axes, though horizontal is most common. Commercial power production horizontal-axis turbines usually have three blades, upwind of their towers. Vertical-axis turbines can be made to varied designs, including the "eggbeater" Darrieus, the giromill with straight blades, the Savonius with scoops suitable for rooftops and ships, airborne with wings tethered to the ground, floating (mounted on a floating platform), and various unconventional types such as with counter-rotating blades. Blades are most commonly made of glass fiber composites, but carbon fiber which is stiffer, stronger, and less dense is also used.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF002', 'A', ARRAY['A']::TEXT[], 'Calling wind intermittent implies that generation depends on variable wind conditions.', '{"C": "Intermittent means output depends on when wind is available.", "D": "Constant output would make the source firm, not intermittent.", "B": "Turbines need wind, so calmer conditions reduce output."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-TS002', 'HDSAT-RW-M23-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A wind turbine is a device that converts the kinetic energy of wind into electrical energy. As of 2024, hundreds of thousands of large turbines, in installations known as wind farms, were generating over 1,136 gigawatts of power, with 117 GW added each year. Wind turbines are an increasingly important source of intermittent renewable energy, and are used in many countries to lower energy costs and reduce reliance on fossil fuels. One study claimed that, as of 2009, wind had the "lowest relative greenhouse gas emissions, the least water consumption demands and the most favorable social impacts" compared to photovoltaic, hydro, geothermal, coal and gas energy sources. Wind turbines are manufactured in a wide range of sizes, with either horizontal or vertical axes, though horizontal is most common. Commercial power production horizontal-axis turbines usually have three blades, upwind of their towers. Vertical-axis turbines can be made to varied designs, including the "eggbeater" Darrieus, the giromill with straight blades, the Savonius with scoops suitable for rooftops and ships, airborne with wings tethered to the ground, floating (mounted on a floating platform), and various unconventional types such as with counter-rotating blades. Blades are most commonly made of glass fiber composites, but carbon fiber which is stiffer, stronger, and less dense is also used.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines wind turbines, describes their scale and environmental advantages, and surveys their designs."}, {"id": "B", "text": "It argues that wind turbines are too small to matter."}, {"id": "C", "text": "It explains how to site a wind farm step by step."}, {"id": "D", "text": "It compares wind power with nuclear power in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Wind turbine", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Wind_turbine', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-TS002', 'A', ARRAY['A']::TEXT[], 'The passage moves from definition and scale to designs.', '{"C": "No siting procedure is given.", "D": "Nuclear power is not discussed.", "B": "The text reports over 1,136 gigawatts of installed capacity."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CE002', 'HDSAT-RW-M23-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A wind turbine is a device that converts the kinetic energy of wind into electrical energy. As of 2024, hundreds of thousands of large turbines, in installations known as wind farms, were generating over 1,136 gigawatts of power, with 117 GW added each year. Wind turbines are an increasingly important source of intermittent renewable energy, and are used in many countries to lower energy costs and reduce reliance on fossil fuels. One study claimed that, as of 2009, wind had the "lowest relative greenhouse gas emissions, the least water consumption demands and the most favorable social impacts" compared to photovoltaic, hydro, geothermal, coal and gas energy sources. Wind turbines are manufactured in a wide range of sizes, with either horizontal or vertical axes, though horizontal is most common. Commercial power production horizontal-axis turbines usually have three blades, upwind of their towers. Vertical-axis turbines can be made to varied designs, including the "eggbeater" Darrieus, the giromill with straight blades, the Savonius with scoops suitable for rooftops and ships, airborne with wings tethered to the ground, floating (mounted on a floating platform), and various unconventional types such as with counter-rotating blades. Blades are most commonly made of glass fiber composites, but carbon fiber which is stiffer, stronger, and less dense is also used.', 'Which quotation from the text most directly supports the claim that wind power has grown to a large scale?', '[{"id": "A", "text": "As of 2024, hundreds of thousands of large turbines, in installations known as wind farms, were generating over 1,136 gigawatts of power, with 117 GW added each year."}, {"id": "B", "text": "Blades are most commonly made of glass fiber composites."}, {"id": "C", "text": "A wind turbine is a device that converts the kinetic energy of wind into electrical energy."}, {"id": "D", "text": "Wind turbines are an increasingly important source of intermittent renewable energy."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Wind turbine", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Wind_turbine', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CE002', 'A', ARRAY['A']::TEXT[], 'The correct quotation gives the installed capacity and annual additions that demonstrate scale.', '{"C": "This sentence defines the device.", "D": "This sentence describes the resource''s importance.", "B": "This sentence describes blade materials."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI003', 'HDSAT-RW-M23-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A lithium-ion battery or Li-ion battery is a type of rechargeable battery that uses the reversible intercalation of lithium ions (Li+) into electronically conducting solids to store energy. There are many different varieties, which are usually categorized by the materials used in the cathode. Compared to other rechargeable battery types, they generally have higher specific energy, energy density, and energy efficiency and a longer cycle life and calendar life. In the three decades since Li-ion batteries were first sold in 1991, their volumetric energy density increased threefold while their cost dropped tenfold. In late 2024, global demand passed 1 terawatt-hour per year, while production capacity was more than twice that. The invention and commercialization of Li-ion batteries has had a large impact on technology, as recognized by the 2019 Nobel Prize in Chemistry, which was awarded to contributors to the development of Li-ion batteries. Li-ion batteries have enabled portable consumer electronics, laptop computers, cellular phones, and electric cars. They are used for grid-scale energy storage and in military and aerospace applications. Li-ion battery sizes are generally not standardised (e.g. in the spirit of the AA battery) and they come in various and unique form factors depending on device and vendor. They typically have a nominal voltage of 3.6 or 3.7 V. M.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Lithium-ion batteries store energy through reversible lithium intercalation and have improved sharply in density and cost."}, {"id": "B", "text": "Lithium-ion batteries store energy by burning lithium metal."}, {"id": "C", "text": "Lithium-ion batteries are non-rechargeable and used once."}, {"id": "D", "text": "Lithium-ion batteries have become more expensive over time."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Lithium-ion battery", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Lithium-ion_battery', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI003', 'A', ARRAY['A']::TEXT[], 'The passage defines the battery, describes its advantages, and traces its improvement and impact.', '{"C": "The text describes them as a type of rechargeable battery.", "D": "The text says their cost dropped tenfold over three decades.", "B": "The text says they use reversible intercalation of lithium ions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF003', 'HDSAT-RW-M23-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A lithium-ion battery or Li-ion battery is a type of rechargeable battery that uses the reversible intercalation of lithium ions (Li+) into electronically conducting solids to store energy. There are many different varieties, which are usually categorized by the materials used in the cathode. Compared to other rechargeable battery types, they generally have higher specific energy, energy density, and energy efficiency and a longer cycle life and calendar life. In the three decades since Li-ion batteries were first sold in 1991, their volumetric energy density increased threefold while their cost dropped tenfold. In late 2024, global demand passed 1 terawatt-hour per year, while production capacity was more than twice that. The invention and commercialization of Li-ion batteries has had a large impact on technology, as recognized by the 2019 Nobel Prize in Chemistry, which was awarded to contributors to the development of Li-ion batteries. Li-ion batteries have enabled portable consumer electronics, laptop computers, cellular phones, and electric cars. They are used for grid-scale energy storage and in military and aerospace applications. Li-ion battery sizes are generally not standardised (e.g. in the spirit of the AA battery) and they come in various and unique form factors depending on device and vendor. They typically have a nominal voltage of 3.6 or 3.7 V. M.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF003', 'A', ARRAY['A']::TEXT[], 'Better energy density at lower cost would make the batteries suitable for a wider range of products.', '{"B": "The text credits them with enabling laptops, phones, and electric cars.", "C": "The text says their cost dropped, not rose.", "D": "The text describes them as rechargeable throughout."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-TS003', 'HDSAT-RW-M23-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A lithium-ion battery or Li-ion battery is a type of rechargeable battery that uses the reversible intercalation of lithium ions (Li+) into electronically conducting solids to store energy. There are many different varieties, which are usually categorized by the materials used in the cathode. Compared to other rechargeable battery types, they generally have higher specific energy, energy density, and energy efficiency and a longer cycle life and calendar life. In the three decades since Li-ion batteries were first sold in 1991, their volumetric energy density increased threefold while their cost dropped tenfold. In late 2024, global demand passed 1 terawatt-hour per year, while production capacity was more than twice that. The invention and commercialization of Li-ion batteries has had a large impact on technology, as recognized by the 2019 Nobel Prize in Chemistry, which was awarded to contributors to the development of Li-ion batteries. Li-ion batteries have enabled portable consumer electronics, laptop computers, cellular phones, and electric cars. They are used for grid-scale energy storage and in military and aerospace applications. Li-ion battery sizes are generally not standardised (e.g. in the spirit of the AA battery) and they come in various and unique form factors depending on device and vendor. They typically have a nominal voltage of 3.6 or 3.7 V. M.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains how to mine lithium in detail."}, {"id": "B", "text": "It argues that lithium-ion batteries are environmentally harmless."}, {"id": "C", "text": "It defines lithium-ion batteries, compares them with other types, and describes their improvement and uses."}, {"id": "D", "text": "It compares lithium-ion batteries with lead-acid batteries in a table."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Lithium-ion battery", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Lithium-ion_battery', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-TS003', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to advantages and then to improvement and applications.', '{"A": "Mining is not discussed.", "D": "No table or detailed comparison with lead-acid batteries appears.", "B": "Environmental harm is not addressed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CE003', 'HDSAT-RW-M23-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A lithium-ion battery or Li-ion battery is a type of rechargeable battery that uses the reversible intercalation of lithium ions (Li+) into electronically conducting solids to store energy. There are many different varieties, which are usually categorized by the materials used in the cathode. Compared to other rechargeable battery types, they generally have higher specific energy, energy density, and energy efficiency and a longer cycle life and calendar life. In the three decades since Li-ion batteries were first sold in 1991, their volumetric energy density increased threefold while their cost dropped tenfold. In late 2024, global demand passed 1 terawatt-hour per year, while production capacity was more than twice that. The invention and commercialization of Li-ion batteries has had a large impact on technology, as recognized by the 2019 Nobel Prize in Chemistry, which was awarded to contributors to the development of Li-ion batteries. Li-ion batteries have enabled portable consumer electronics, laptop computers, cellular phones, and electric cars. They are used for grid-scale energy storage and in military and aerospace applications. Li-ion battery sizes are generally not standardised (e.g. in the spirit of the AA battery) and they come in various and unique form factors depending on device and vendor. They typically have a nominal voltage of 3.6 or 3.7 V. M.', 'Which quotation from the text most directly supports the claim that lithium-ion batteries improved dramatically over time?', '[{"id": "A", "text": "They are used for grid-scale energy storage and in military and aerospace applications."}, {"id": "B", "text": "Compared to other rechargeable battery types, they generally have higher specific energy and energy density."}, {"id": "C", "text": "In the three decades since Li-ion batteries were first sold in 1991, their volumetric energy density increased threefold while their cost dropped tenfold."}, {"id": "D", "text": "A lithium-ion battery is a type of rechargeable battery that uses the reversible intercalation of lithium ions to store energy."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Lithium-ion battery", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Lithium-ion_battery', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CE003', 'C', ARRAY['C']::TEXT[], 'The correct quotation gives the threefold density gain and tenfold cost reduction.', '{"D": "This sentence defines the battery.", "B": "This sentence compares battery types.", "A": "This sentence lists applications."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI004', 'HDSAT-RW-M23-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Desalination is the artificial process by which salt water (generally sea water) is converted to fresh water. More generally, desalination is the removal of salts and minerals from a substance. It is possible to desalinate saltwater, especially sea water, to produce water for human consumption or irrigation, producing brine as a by-product. Interest in desalination mostly focuses on cost-effective provision of fresh water for human use. Along with recycled wastewater, it is one of the few water resources independent of rainfall. As stress on the need for freshwater intensifies globally, desalination has become a key part of strategies for global water security. According to a 2019 review in Science of the Total Environment, around 95 million cubic meters per day of desalinated water is produced worldwide, and the demand for desalinated water is expected to grow significantly to help close the global water supply gap. Due to its energy consumption, desalinating sea water is generally more costly than fresh water from surface water or groundwater, water recycling and water conservation. However, these alternatives are not always available and depletion of reserves is a critical problem worldwide. Desalination processes use either thermal methods (in the case of distillation) or membrane-based methods (e.g. in the case of reverse osmosis).', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Desalination turns salt water into fresh water and is increasingly important for water security despite its cost and energy use."}, {"id": "B", "text": "Desalination is cheaper than all other water sources."}, {"id": "C", "text": "Desalination adds salt to fresh water for irrigation."}, {"id": "D", "text": "Desalination depends entirely on rainfall."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Desalination", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Desalination', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI004', 'A', ARRAY['A']::TEXT[], 'The passage defines desalination, describes its scale and cost, and explains its role in water supply.', '{"C": "The text says desalination converts salt water to fresh water.", "B": "The text says it is generally more costly than surface water, groundwater, recycling, and conservation.", "D": "The text calls it one of the few water resources independent of rainfall."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF004', 'HDSAT-RW-M23-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Desalination is the artificial process by which salt water (generally sea water) is converted to fresh water. More generally, desalination is the removal of salts and minerals from a substance. It is possible to desalinate saltwater, especially sea water, to produce water for human consumption or irrigation, producing brine as a by-product. Interest in desalination mostly focuses on cost-effective provision of fresh water for human use. Along with recycled wastewater, it is one of the few water resources independent of rainfall. As stress on the need for freshwater intensifies globally, desalination has become a key part of strategies for global water security. According to a 2019 review in Science of the Total Environment, around 95 million cubic meters per day of desalinated water is produced worldwide, and the demand for desalinated water is expected to grow significantly to help close the global water supply gap. Due to its energy consumption, desalinating sea water is generally more costly than fresh water from surface water or groundwater, water recycling and water conservation. However, these alternatives are not always available and depletion of reserves is a critical problem worldwide. Desalination processes use either thermal methods (in the case of distillation) or membrane-based methods (e.g. in the case of reverse osmosis).
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF004', 'B', ARRAY['B']::TEXT[], 'Desalination''s higher cost makes it a fallback where cheaper freshwater sources cannot meet demand.', '{"D": "The text says the alternatives are not always available and depletion is a critical problem.", "C": "Abundant rainfall would reduce the need for desalination.", "A": "The text notes desalination''s energy consumption as a cost."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-TS004', 'HDSAT-RW-M23-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Desalination is the artificial process by which salt water (generally sea water) is converted to fresh water. More generally, desalination is the removal of salts and minerals from a substance. It is possible to desalinate saltwater, especially sea water, to produce water for human consumption or irrigation, producing brine as a by-product. Interest in desalination mostly focuses on cost-effective provision of fresh water for human use. Along with recycled wastewater, it is one of the few water resources independent of rainfall. As stress on the need for freshwater intensifies globally, desalination has become a key part of strategies for global water security. According to a 2019 review in Science of the Total Environment, around 95 million cubic meters per day of desalinated water is produced worldwide, and the demand for desalinated water is expected to grow significantly to help close the global water supply gap. Due to its energy consumption, desalinating sea water is generally more costly than fresh water from surface water or groundwater, water recycling and water conservation. However, these alternatives are not always available and depletion of reserves is a critical problem worldwide. Desalination processes use either thermal methods (in the case of distillation) or membrane-based methods (e.g. in the case of reverse osmosis).', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates the construction of a single desalination plant."}, {"id": "B", "text": "It argues that desalination should be abandoned."}, {"id": "C", "text": "It compares desalination with bottled water."}, {"id": "D", "text": "It defines desalination, describes the demand for it, and explains its costs and methods."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Desalination", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Desalination', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-TS004', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition to need and then to cost and technology.', '{"A": "No individual plant is described.", "C": "Bottled water is not mentioned.", "B": "The text presents desalination as a key part of water security strategies."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CE004', 'HDSAT-RW-M23-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Desalination is the artificial process by which salt water (generally sea water) is converted to fresh water. More generally, desalination is the removal of salts and minerals from a substance. It is possible to desalinate saltwater, especially sea water, to produce water for human consumption or irrigation, producing brine as a by-product. Interest in desalination mostly focuses on cost-effective provision of fresh water for human use. Along with recycled wastewater, it is one of the few water resources independent of rainfall. As stress on the need for freshwater intensifies globally, desalination has become a key part of strategies for global water security. According to a 2019 review in Science of the Total Environment, around 95 million cubic meters per day of desalinated water is produced worldwide, and the demand for desalinated water is expected to grow significantly to help close the global water supply gap. Due to its energy consumption, desalinating sea water is generally more costly than fresh water from surface water or groundwater, water recycling and water conservation. However, these alternatives are not always available and depletion of reserves is a critical problem worldwide. Desalination processes use either thermal methods (in the case of distillation) or membrane-based methods (e.g. in the case of reverse osmosis).', 'Which quotation from the text most directly supports the claim that desalination does not depend on rainfall?', '[{"id": "A", "text": "It is possible to desalinate saltwater to produce water for human consumption or irrigation, producing brine as a by-product."}, {"id": "B", "text": "Desalination processes use either thermal methods or membrane-based methods."}, {"id": "C", "text": "Desalination is the artificial process by which salt water is converted to fresh water."}, {"id": "D", "text": "Along with recycled wastewater, it is one of the few water resources independent of rainfall."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Desalination", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Desalination', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CE004', 'D', ARRAY['D']::TEXT[], 'The correct quotation explicitly calls desalination independent of rainfall.', '{"C": "This sentence defines the process.", "A": "This sentence describes products and by-products.", "B": "This sentence describes the methods used."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI005', 'HDSAT-RW-M23-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Geothermal energy is thermal energy extracted from the Earth''s crust. It combines energy from the planet''s formation and from radioactive decay. Geothermal energy has been exploited as a source of heat and/or electric power for millennia. Geothermal heating, using water from hot springs, for example, has been used for bathing since Paleolithic times and for space heating since Roman times. Geothermal power (generation of electricity from geothermal energy) has been used since the 20th century. Geothermal power plants produce power at a constant rate, regardless of weather conditions. Geothermal resources are theoretically more than adequate to supply humanity''s energy needs. Most extraction occurs in areas near tectonic plate boundaries. The cost of generating geothermal power decreased by 25% during the 1980s and 1990s. Technological advances continued to reduce costs and thereby expand the amount of viable resources. In 2021, the US Department of Energy estimated that power from a newly built plant costs about $0.05/kWh. 16 gigawatts (GW) of geothermal power was available worldwide in 2025, which was less than 1% of renewable power capacity. An additional 28 gigawatts provided heat for district heating, space heating, spas, industrial processes, desalination, and agricultural applications as of 2010. As of 2019 the industry employed about one hundred thousand people.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Geothermal power output varies with weather conditions."}, {"id": "B", "text": "Geothermal energy has only been used since the 21st century."}, {"id": "C", "text": "Geothermal energy is generated by burning underground fossil fuels."}, {"id": "D", "text": "Geothermal energy taps heat from the Earth''s crust for heating and electricity, producing steady power but remaining a small share of capacity."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Geothermal energy", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Geothermal_energy', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI005', 'D', ARRAY['D']::TEXT[], 'The passage describes geothermal resources, their history, their reliability, and their current scale.', '{"C": "The text describes thermal energy extracted from the Earth''s crust.", "A": "The text says geothermal plants produce power at a constant rate regardless of weather.", "B": "The text says geothermal heating has been used since Paleolithic and Roman times."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF005', 'HDSAT-RW-M23-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Geothermal energy is thermal energy extracted from the Earth''s crust. It combines energy from the planet''s formation and from radioactive decay. Geothermal energy has been exploited as a source of heat and/or electric power for millennia. Geothermal heating, using water from hot springs, for example, has been used for bathing since Paleolithic times and for space heating since Roman times. Geothermal power (generation of electricity from geothermal energy) has been used since the 20th century. Geothermal power plants produce power at a constant rate, regardless of weather conditions. Geothermal resources are theoretically more than adequate to supply humanity''s energy needs. Most extraction occurs in areas near tectonic plate boundaries. The cost of generating geothermal power decreased by 25% during the 1980s and 1990s. Technological advances continued to reduce costs and thereby expand the amount of viable resources. In 2021, the US Department of Energy estimated that power from a newly built plant costs about $0.05/kWh. 16 gigawatts (GW) of geothermal power was available worldwide in 2025, which was less than 1% of renewable power capacity. An additional 28 gigawatts provided heat for district heating, space heating, spas, industrial processes, desalination, and agricultural applications as of 2010. As of 2019 the industry employed about one hundred thousand people.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF005', 'A', ARRAY['A']::TEXT[], 'Constant, weather-independent generation gives geothermal a reliability advantage over variable sources.', '{"B": "The text contrasts constant geothermal output with weather-dependent sources.", "D": "The text says output is constant regardless of weather, which includes night.", "C": "Geothermal energy comes from the Earth''s crust, not sunlight."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-TS005', 'HDSAT-RW-M23-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Geothermal energy is thermal energy extracted from the Earth''s crust. It combines energy from the planet''s formation and from radioactive decay. Geothermal energy has been exploited as a source of heat and/or electric power for millennia. Geothermal heating, using water from hot springs, for example, has been used for bathing since Paleolithic times and for space heating since Roman times. Geothermal power (generation of electricity from geothermal energy) has been used since the 20th century. Geothermal power plants produce power at a constant rate, regardless of weather conditions. Geothermal resources are theoretically more than adequate to supply humanity''s energy needs. Most extraction occurs in areas near tectonic plate boundaries. The cost of generating geothermal power decreased by 25% during the 1980s and 1990s. Technological advances continued to reduce costs and thereby expand the amount of viable resources. In 2021, the US Department of Energy estimated that power from a newly built plant costs about $0.05/kWh. 16 gigawatts (GW) of geothermal power was available worldwide in 2025, which was less than 1% of renewable power capacity. An additional 28 gigawatts provided heat for district heating, space heating, spas, industrial processes, desalination, and agricultural applications as of 2010. As of 2019 the industry employed about one hundred thousand people.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that geothermal energy can supply all human needs immediately."}, {"id": "B", "text": "It compares geothermal energy with nuclear fusion."}, {"id": "C", "text": "It explains how to drill a geothermal well step by step."}, {"id": "D", "text": "It defines geothermal energy, traces its uses, and describes its costs, scale, and applications."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Geothermal energy", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Geothermal_energy', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-TS005', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition and history to economics and current use.', '{"C": "No drilling procedure is given.", "B": "Nuclear fusion is not mentioned.", "A": "The text says resources are theoretically adequate but notes geothermal was less than 1% of renewable capacity."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CE005', 'HDSAT-RW-M23-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Geothermal energy is thermal energy extracted from the Earth''s crust. It combines energy from the planet''s formation and from radioactive decay. Geothermal energy has been exploited as a source of heat and/or electric power for millennia. Geothermal heating, using water from hot springs, for example, has been used for bathing since Paleolithic times and for space heating since Roman times. Geothermal power (generation of electricity from geothermal energy) has been used since the 20th century. Geothermal power plants produce power at a constant rate, regardless of weather conditions. Geothermal resources are theoretically more than adequate to supply humanity''s energy needs. Most extraction occurs in areas near tectonic plate boundaries. The cost of generating geothermal power decreased by 25% during the 1980s and 1990s. Technological advances continued to reduce costs and thereby expand the amount of viable resources. In 2021, the US Department of Energy estimated that power from a newly built plant costs about $0.05/kWh. 16 gigawatts (GW) of geothermal power was available worldwide in 2025, which was less than 1% of renewable power capacity. An additional 28 gigawatts provided heat for district heating, space heating, spas, industrial processes, desalination, and agricultural applications as of 2010. As of 2019 the industry employed about one hundred thousand people.', 'Which quotation from the text most directly supports the claim that people have used geothermal heat for a very long time?', '[{"id": "A", "text": "Geothermal energy is thermal energy extracted from the Earth''s crust."}, {"id": "B", "text": "In 2021, the US Department of Energy estimated that power from a newly built plant costs about $0.05/kWh."}, {"id": "C", "text": "Geothermal heating, using water from hot springs, for example, has been used for bathing since Paleolithic times and for space heating since Roman times."}, {"id": "D", "text": "Geothermal power plants produce power at a constant rate, regardless of weather conditions."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Geothermal energy", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Geothermal_energy', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CE005', 'C', ARRAY['C']::TEXT[], 'The correct quotation dates geothermal heating to the Paleolithic and Roman periods.', '{"A": "This sentence defines geothermal energy.", "D": "This sentence describes reliability.", "B": "This sentence gives a cost estimate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI006', 'HDSAT-RW-M23-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A light-emitting diode (LED) is an electronic component that uses a semiconductor to emit light when current flows through it. Electrons in the semiconductor recombine with electron holes, thereby releasing energy in the form of photons. The color of the light (corresponding to the energy of the photons) is determined by the energy required for electrons to cross the band gap of the semiconductor. White light is obtained by using multiple semiconductors or a layer of light-emitting phosphor on the semiconductor device. Appearing as practical electronic components in 1962, the earliest LEDs emitted low-intensity infrared (IR) light. Infrared LEDs are used in remote-control circuits, such as those used with a wide variety of consumer electronics. The first visible-light LEDs were of low intensity and limited to red. Early LEDs were often used as indicator lamps, replacing small incandescent bulbs, and in seven-segment displays. Later developments produced LEDs available in visible, ultraviolet (UV), and infrared wavelengths with high, low, or intermediate light output, such as white LEDs suitable for room and outdoor lighting. LEDs have also given rise to new types of displays and sensors, while their high switching rates have uses in advanced communications technology.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "LEDs produce light by heating a metal filament."}, {"id": "B", "text": "LEDs can emit only infrared light."}, {"id": "C", "text": "LED colors are determined by the shape of the plastic casing."}, {"id": "D", "text": "LEDs emit light when current passes through a semiconductor, with colors set by the material''s band gap and uses expanding since 1962."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Light-emitting diode", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Light-emitting_diode', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI006', 'D', ARRAY['D']::TEXT[], 'The passage explains the LED mechanism, the basis of its color, and its development and applications.', '{"A": "The text says LEDs use a semiconductor and recombining electrons and holes release photons.", "B": "The text says later LEDs became available in visible, ultraviolet, and infrared wavelengths.", "C": "The text says color is determined by the energy required for electrons to cross the band gap."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF006', 'HDSAT-RW-M23-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A light-emitting diode (LED) is an electronic component that uses a semiconductor to emit light when current flows through it. Electrons in the semiconductor recombine with electron holes, thereby releasing energy in the form of photons. The color of the light (corresponding to the energy of the photons) is determined by the energy required for electrons to cross the band gap of the semiconductor. White light is obtained by using multiple semiconductors or a layer of light-emitting phosphor on the semiconductor device. Appearing as practical electronic components in 1962, the earliest LEDs emitted low-intensity infrared (IR) light. Infrared LEDs are used in remote-control circuits, such as those used with a wide variety of consumer electronics. The first visible-light LEDs were of low intensity and limited to red. Early LEDs were often used as indicator lamps, replacing small incandescent bulbs, and in seven-segment displays. Later developments produced LEDs available in visible, ultraviolet (UV), and infrared wavelengths with high, low, or intermediate light output, such as white LEDs suitable for room and outdoor lighting. LEDs have also given rise to new types of displays and sensors, while their high switching rates have uses in advanced communications technology.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF006', 'C', ARRAY['C']::TEXT[], 'Since band gap determines photon energy, a different color requires a semiconductor with a different gap.', '{"B": "The text ties color to the band gap and says white light uses multiple semiconductors or a phosphor layer.", "A": "Current alone does not change the band gap.", "D": "The casing is not described as setting color."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-TS006', 'HDSAT-RW-M23-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A light-emitting diode (LED) is an electronic component that uses a semiconductor to emit light when current flows through it. Electrons in the semiconductor recombine with electron holes, thereby releasing energy in the form of photons. The color of the light (corresponding to the energy of the photons) is determined by the energy required for electrons to cross the band gap of the semiconductor. White light is obtained by using multiple semiconductors or a layer of light-emitting phosphor on the semiconductor device. Appearing as practical electronic components in 1962, the earliest LEDs emitted low-intensity infrared (IR) light. Infrared LEDs are used in remote-control circuits, such as those used with a wide variety of consumer electronics. The first visible-light LEDs were of low intensity and limited to red. Early LEDs were often used as indicator lamps, replacing small incandescent bulbs, and in seven-segment displays. Later developments produced LEDs available in visible, ultraviolet (UV), and infrared wavelengths with high, low, or intermediate light output, such as white LEDs suitable for room and outdoor lighting. LEDs have also given rise to new types of displays and sensors, while their high switching rates have uses in advanced communications technology.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that incandescent bulbs are more efficient."}, {"id": "B", "text": "It explains how to manufacture a seven-segment display."}, {"id": "C", "text": "It compares LEDs with candles in detail."}, {"id": "D", "text": "It explains how LEDs produce light and color, then traces their development and expanding uses."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Light-emitting diode", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Light-emitting_diode', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-TS006', 'D', ARRAY['D']::TEXT[], 'The passage moves from mechanism to history and applications.', '{"C": "Candles are not mentioned.", "B": "No manufacturing process is described.", "A": "The text says early LEDs replaced small incandescent bulbs as indicators."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CE006', 'HDSAT-RW-M23-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A light-emitting diode (LED) is an electronic component that uses a semiconductor to emit light when current flows through it. Electrons in the semiconductor recombine with electron holes, thereby releasing energy in the form of photons. The color of the light (corresponding to the energy of the photons) is determined by the energy required for electrons to cross the band gap of the semiconductor. White light is obtained by using multiple semiconductors or a layer of light-emitting phosphor on the semiconductor device. Appearing as practical electronic components in 1962, the earliest LEDs emitted low-intensity infrared (IR) light. Infrared LEDs are used in remote-control circuits, such as those used with a wide variety of consumer electronics. The first visible-light LEDs were of low intensity and limited to red. Early LEDs were often used as indicator lamps, replacing small incandescent bulbs, and in seven-segment displays. Later developments produced LEDs available in visible, ultraviolet (UV), and infrared wavelengths with high, low, or intermediate light output, such as white LEDs suitable for room and outdoor lighting. LEDs have also given rise to new types of displays and sensors, while their high switching rates have uses in advanced communications technology.', 'Which quotation from the text most directly supports the claim that early LEDs were not suitable for general lighting?', '[{"id": "A", "text": "LEDs have also given rise to new types of displays and sensors."}, {"id": "B", "text": "White light is obtained by using multiple semiconductors or a layer of light-emitting phosphor on the semiconductor device."}, {"id": "C", "text": "The first visible-light LEDs were of low intensity and limited to red."}, {"id": "D", "text": "A light-emitting diode is an electronic component that uses a semiconductor to emit light when current flows through it."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Light-emitting diode", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Light-emitting_diode', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CE006', 'C', ARRAY['C']::TEXT[], 'Low intensity and only red output show why early LEDs could not light rooms.', '{"D": "This sentence defines the LED.", "B": "This sentence describes how white light is produced.", "A": "This sentence describes newer applications."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI007', 'HDSAT-RW-M23-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A radio telescope is a specialized antenna and radio receiver used to detect radio waves from astronomical radio sources in the sky. Radio telescopes are the main observing instrument used in radio astronomy, which studies the radio frequency portion of the electromagnetic spectrum, just as optical telescopes are used to make observations in the visible portion of the spectrum in traditional optical astronomy. Unlike optical telescopes, radio telescopes can be used in the daytime as well as at night. Since astronomical radio sources such as planets, stars, nebulas and galaxies are very far away, the radio waves coming from them are extremely weak, so radio telescopes require very large antennas to collect enough radio energy to study them, and extremely sensitive receiving equipment. Radio telescopes are typically large parabolic ("dish") antennas similar to those employed in tracking and communicating with satellites and space probes. They may be used individually or linked together electronically in an array. Radio observatories are preferentially located far from major centers of population to avoid electromagnetic interference (EMI) from radio, television, radar, motor vehicles, and other man-made electronic devices. Radio waves from space were first detected by engineer Karl Guthe Jansky in 1932 at Bell Telephone Laboratories in Holmdel, New Jersey using an antenna built to study radio receiver noise.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Radio telescopes detect visible light from nearby planets."}, {"id": "B", "text": "Radio telescopes work only at night."}, {"id": "C", "text": "Radio telescopes are small devices used to amplify radio broadcasts."}, {"id": "D", "text": "Radio telescopes detect faint radio waves from space using large antennas, often in arrays and away from interference."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Radio telescope", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Radio_telescope', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI007', 'D', ARRAY['D']::TEXT[], 'The passage defines radio telescopes, explains why they are large and remotely located, and notes their history.', '{"A": "The text says they detect radio waves from astronomical sources.", "B": "The text says they can be used in the daytime as well as at night.", "C": "The text says they require very large antennas."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF007', 'HDSAT-RW-M23-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A radio telescope is a specialized antenna and radio receiver used to detect radio waves from astronomical radio sources in the sky. Radio telescopes are the main observing instrument used in radio astronomy, which studies the radio frequency portion of the electromagnetic spectrum, just as optical telescopes are used to make observations in the visible portion of the spectrum in traditional optical astronomy. Unlike optical telescopes, radio telescopes can be used in the daytime as well as at night. Since astronomical radio sources such as planets, stars, nebulas and galaxies are very far away, the radio waves coming from them are extremely weak, so radio telescopes require very large antennas to collect enough radio energy to study them, and extremely sensitive receiving equipment. Radio telescopes are typically large parabolic ("dish") antennas similar to those employed in tracking and communicating with satellites and space probes. They may be used individually or linked together electronically in an array. Radio observatories are preferentially located far from major centers of population to avoid electromagnetic interference (EMI) from radio, television, radar, motor vehicles, and other man-made electronic devices. Radio waves from space were first detected by engineer Karl Guthe Jansky in 1932 at Bell Telephone Laboratories in Holmdel, New Jersey using an antenna built to study radio receiver noise.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF007', 'C', ARRAY['C']::TEXT[], 'Weak signals demand large collecting area and sensitive electronics.', '{"D": "The text states that weak signals require very large antennas and extremely sensitive receiving equipment.", "A": "Small antennas would collect too little energy.", "B": "The weakness is in radio waves, not visible light."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-TS007', 'HDSAT-RW-M23-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A radio telescope is a specialized antenna and radio receiver used to detect radio waves from astronomical radio sources in the sky. Radio telescopes are the main observing instrument used in radio astronomy, which studies the radio frequency portion of the electromagnetic spectrum, just as optical telescopes are used to make observations in the visible portion of the spectrum in traditional optical astronomy. Unlike optical telescopes, radio telescopes can be used in the daytime as well as at night. Since astronomical radio sources such as planets, stars, nebulas and galaxies are very far away, the radio waves coming from them are extremely weak, so radio telescopes require very large antennas to collect enough radio energy to study them, and extremely sensitive receiving equipment. Radio telescopes are typically large parabolic ("dish") antennas similar to those employed in tracking and communicating with satellites and space probes. They may be used individually or linked together electronically in an array. Radio observatories are preferentially located far from major centers of population to avoid electromagnetic interference (EMI) from radio, television, radar, motor vehicles, and other man-made electronic devices. Radio waves from space were first detected by engineer Karl Guthe Jansky in 1932 at Bell Telephone Laboratories in Holmdel, New Jersey using an antenna built to study radio receiver noise.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that optical telescopes are obsolete."}, {"id": "B", "text": "It explains how to build a radio receiver at home."}, {"id": "C", "text": "It defines radio telescopes, compares them with optical telescopes, and explains their design, siting, and history."}, {"id": "D", "text": "It compares radio astronomy with astrology."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Radio telescope", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Radio_telescope', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-TS007', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to comparison and then to practical requirements and discovery.', '{"B": "No construction instructions are given.", "D": "Astrology is not mentioned.", "A": "The text presents optical and radio astronomy as complementary."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CE007', 'HDSAT-RW-M23-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A radio telescope is a specialized antenna and radio receiver used to detect radio waves from astronomical radio sources in the sky. Radio telescopes are the main observing instrument used in radio astronomy, which studies the radio frequency portion of the electromagnetic spectrum, just as optical telescopes are used to make observations in the visible portion of the spectrum in traditional optical astronomy. Unlike optical telescopes, radio telescopes can be used in the daytime as well as at night. Since astronomical radio sources such as planets, stars, nebulas and galaxies are very far away, the radio waves coming from them are extremely weak, so radio telescopes require very large antennas to collect enough radio energy to study them, and extremely sensitive receiving equipment. Radio telescopes are typically large parabolic ("dish") antennas similar to those employed in tracking and communicating with satellites and space probes. They may be used individually or linked together electronically in an array. Radio observatories are preferentially located far from major centers of population to avoid electromagnetic interference (EMI) from radio, television, radar, motor vehicles, and other man-made electronic devices. Radio waves from space were first detected by engineer Karl Guthe Jansky in 1932 at Bell Telephone Laboratories in Holmdel, New Jersey using an antenna built to study radio receiver noise.', 'Which quotation from the text most directly supports the claim that radio astronomy is not limited to nighttime?', '[{"id": "A", "text": "A radio telescope is a specialized antenna and radio receiver used to detect radio waves from astronomical radio sources in the sky."}, {"id": "B", "text": "Radio waves from space were first detected by engineer Karl Guthe Jansky in 1932."}, {"id": "C", "text": "Unlike optical telescopes, radio telescopes can be used in the daytime as well as at night."}, {"id": "D", "text": "Radio telescopes are typically large parabolic antennas similar to those employed in tracking and communicating with satellites."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Radio telescope", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Radio_telescope', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CE007', 'C', ARRAY['C']::TEXT[], 'The correct quotation explicitly says radio telescopes work in daylight and darkness.', '{"A": "This sentence defines the instrument.", "D": "This sentence describes antenna shape.", "B": "This sentence describes the first detection."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-CI008', 'HDSAT-RW-M23-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A semiconductor is a material with electrical conductivity between that of a conductor and an insulator. Its conductivity can be modified by adding impurities ("doping") to its crystal structure. When two regions with different doping levels are present in the same crystal, they form a semiconductor junction. The term "semiconductors" is sometimes used to refer to semiconductor devices such as microchips and computer processors, which work using the physical properties of semiconductors. The behavior of charge carriers, which include electrons, ions, and electron holes, at these junctions is the basis of diodes, transistors, and most modern electronics. Some examples of semiconductors are silicon, germanium, gallium arsenide, and elements near the so-called "metalloid staircase" on the periodic table. After silicon, gallium arsenide is the second-most common semiconductor and is used in laser diodes, solar cells, microwave-frequency integrated circuits, and others. Silicon is a critical element for fabricating most electronic circuits. Semiconductor devices can display a range of different useful properties, such as passing current more easily in one direction than the other, showing variable resistance, and having sensitivity to light or heat.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Semiconductors occur only in living organisms."}, {"id": "B", "text": "Semiconductors are perfect insulators that cannot conduct electricity."}, {"id": "C", "text": "Doping makes a semiconductor useless for electronics."}, {"id": "D", "text": "Semiconductors have conductivity between conductors and insulators, can be tuned by doping, and underlie modern electronics."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Semiconductor", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Semiconductor', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-CI008', 'D', ARRAY['D']::TEXT[], 'The passage defines semiconductors, explains doping and junctions, and describes their role in devices.', '{"B": "The text says their conductivity is between that of a conductor and an insulator.", "A": "The text lists silicon, germanium, and gallium arsenide.", "C": "The text says doping modifies conductivity and enables junctions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M23-INF008', 'HDSAT-RW-M23-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A semiconductor is a material with electrical conductivity between that of a conductor and an insulator. Its conductivity can be modified by adding impurities ("doping") to its crystal structure. When two regions with different doping levels are present in the same crystal, they form a semiconductor junction. The term "semiconductors" is sometimes used to refer to semiconductor devices such as microchips and computer processors, which work using the physical properties of semiconductors. The behavior of charge carriers, which include electrons, ions, and electron holes, at these junctions is the basis of diodes, transistors, and most modern electronics. Some examples of semiconductors are silicon, germanium, gallium arsenide, and elements near the so-called "metalloid staircase" on the periodic table. After silicon, gallium arsenide is the second-most common semiconductor and is used in laser diodes, solar cells, microwave-frequency integrated circuits, and others. Silicon is a critical element for fabricating most electronic circuits. Semiconductor devices can display a range of different useful properties, such as passing current more easily in one direction than the other, showing variable resistance, and having sensitivity to light or heat.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M23-INF008', 'A', ARRAY['A']::TEXT[], 'Controlled doping lets engineers create the junctions that make diodes and transistors work.', '{"B": "Doping is used to create regions with different properties and form junctions.", "C": "The text places semiconductor conductivity below that of a conductor.", "D": "Junctions are formed by regions with different doping levels."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
